const LIFECYCLE_STAGES = [
    { id: 'request-received', label: 'Request Received' },
    { id: 'verification-call', label: 'Verification Call' },
    { id: 'consultation', label: 'Consultation' },
    { id: 'action-plan', label: 'Action Plan' },
    { id: 'resolution', label: 'Resolution' },
];
export const buildStages = (current) => {
    const currentIndex = LIFECYCLE_STAGES.findIndex((stage) => stage.id === current);
    return LIFECYCLE_STAGES.map((stage, index) => ({
        id: stage.id,
        label: stage.label,
        completed: index <= currentIndex,
    }));
};
